package com.meterflow.budgets;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity @Table(name="usage_budgets",uniqueConstraints=@UniqueConstraint(columnNames={"customer_id","period"}))public class UsageBudget{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="customer_id",nullable=false)private String customerId;@Column(nullable=false)private String period;@Column(nullable=false,precision=18,scale=2)private BigDecimal amount;@Column(nullable=false)private String currency;@Column(nullable=false)private String notified="";@Column(nullable=false)private Instant updatedAt=Instant.now();protected UsageBudget(){}public UsageBudget(String c,String p,BigDecimal a,String u){customerId=c;period=p;amount=a;currency=u;}public UUID getId(){return id;}public String getCustomerId(){return customerId;}public String getPeriod(){return period;}public BigDecimal getAmount(){return amount;}public String getCurrency(){return currency;}public String getNotified(){return notified;}public void mark(int n){notified=notified.isBlank()?String.valueOf(n):notified+","+n;updatedAt=Instant.now();}public void update(BigDecimal a){if(a==null||a.signum()<=0)throw new IllegalArgumentException("Budget must be positive");amount=a;updatedAt=Instant.now();notified="";}public boolean wasNotified(int n){return Arrays.asList(notified.split(",")).contains(String.valueOf(n));}}
